package multipartbody

import (
	"errors"
	"io"
	"mime"
	"mime/multipart"
	"strings"
	"testing"
)

type errReader struct{ err error }

func (r *errReader) Read([]byte) (int, error) { return 0, r.err }

func parseParts(t *testing.T, contentType string, body io.Reader) []*multipart.Part {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected media type: %q", mediaType)
	}

	reader := multipart.NewReader(body, params["boundary"])
	var parts []*multipart.Part
	for {
		part, err := reader.NextPart()
		if errors.Is(err, io.EOF) {
			return parts
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		data, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		// Re-wrap so callers can read the part content again.
		parts = append(parts, &multipart.Part{Header: part.Header})
		partContents[len(parts)-1] = string(data)
	}
}

var partContents = map[int]string{}

func TestNewFile_EncodesSingleFilePart(t *testing.T) {
	contentType, body, err := NewFile("file", "recording.mp3", strings.NewReader("audio"))
	if err != nil {
		t.Fatalf("NewFile error: %v", err)
	}
	if body.Len() == 0 {
		t.Fatalf("expected non-empty body")
	}

	parts := parseParts(t, contentType, body)
	if len(parts) != 1 {
		t.Fatalf("expected 1 part, got %d", len(parts))
	}
	if got := parts[0].FormName(); got != "file" {
		t.Fatalf("unexpected form name: %q", got)
	}
	if got := parts[0].FileName(); got != "recording.mp3" {
		t.Fatalf("unexpected file name: %q", got)
	}
	if got := partContents[0]; got != "audio" {
		t.Fatalf("unexpected content: %q", got)
	}
}

func TestNewFileWithFields_WritesFieldsBeforeFile(t *testing.T) {
	contentType, body, err := NewFileWithFields(
		"file",
		"contract.pdf",
		strings.NewReader("pdf-bytes"),
		Field{Name: "deal_id", Value: "42"},
		Field{Name: "lead_id", Value: "adf21080-0e10-11eb-879b-05d71fb426ec"},
	)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	parts := parseParts(t, contentType, body)
	if len(parts) != 3 {
		t.Fatalf("expected 3 parts, got %d", len(parts))
	}

	if got := parts[0].FormName(); got != "deal_id" {
		t.Fatalf("unexpected first field: %q", got)
	}
	if got := partContents[0]; got != "42" {
		t.Fatalf("unexpected deal_id value: %q", got)
	}
	if got := parts[1].FormName(); got != "lead_id" {
		t.Fatalf("unexpected second field: %q", got)
	}
	if got := partContents[1]; got != "adf21080-0e10-11eb-879b-05d71fb426ec" {
		t.Fatalf("unexpected lead_id value: %q", got)
	}

	if got := parts[2].FormName(); got != "file" {
		t.Fatalf("unexpected file field: %q", got)
	}
	if got := parts[2].FileName(); got != "contract.pdf" {
		t.Fatalf("unexpected file name: %q", got)
	}
	if got := partContents[2]; got != "pdf-bytes" {
		t.Fatalf("unexpected file content: %q", got)
	}
}

func TestNewFileWithFields_Validation(t *testing.T) {
	tests := []struct {
		name      string
		fieldName string
		fileName  string
		src       io.Reader
		fields    []Field
	}{
		{name: "missing field name", fileName: "a.txt", src: strings.NewReader("x")},
		{name: "missing file name", fieldName: "file", src: strings.NewReader("x")},
		{name: "missing source", fieldName: "file", fileName: "a.txt"},
		{name: "empty form field name", fieldName: "file", fileName: "a.txt", src: strings.NewReader("x"), fields: []Field{{Value: "1"}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, _, err := NewFileWithFields(tt.fieldName, tt.fileName, tt.src, tt.fields...); err == nil {
				t.Fatalf("expected error")
			}
		})
	}
}

func TestNewFileWithFields_PropagatesSourceReadError(t *testing.T) {
	boom := errors.New("boom")
	_, _, err := NewFileWithFields("file", "a.txt", &errReader{err: boom})
	if !errors.Is(err, boom) {
		t.Fatalf("expected wrapped source error, got %v", err)
	}
}
