''', '''// Upload stores content in Pipedrive under fileName (POST /files) and
// returns the created File. Associate it with an item through
// WithFileDealID, WithFilePersonID, WithFileOrganizationID,
// WithFileProductID, WithFileActivityID, WithFileLeadID or
// WithFileProjectID.
//
// The multipart body is buffered in memory so the request can be retried
// on 429/5xx responses under the active retry policy. content is read to
// EOF but not closed.
func (s *FilesService) Upload(ctx context.Context, fileName string, content io.Reader, opts ...UploadFileOption) (*File, error) {
	if fileName == "" || content == nil {
		return nil, fmt.Errorf("file name and content are required")
	}
	cfg := newUploadFileOptions(opts)

	fields, err := cfg.payload.toFields()
	if err != nil {
		return nil, err
	}
	contentType, body, err := multipartbody.NewFileWithFields("file", fileName, content, fields...)
	if err != nil {
		return nil, err
	}
	return s.add(ctx, body, contentType, cfg.filesOptions)
}

// Add sends a caller-encoded request body to POST /files with the given
// Content-Type. It is the low-level counterpart of Upload for callers who
// assemble the multipart/form-data body themselves; most callers should
// use Upload instead. A body net/http cannot replay on its own (for
// example an *os.File) is buffered in memory so retries can resend it.
func (s *FilesService) Add(ctx context.Context, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
	if body == nil {
		return nil, fmt.Errorf("file body is required")
	}
	if contentType == "" {
		return nil, fmt.Errorf("content type is required")
	}
	return s.add(ctx, body, contentType, newFilesOptions(opts))
}

func (s *FilesService) add(ctx context.Context, body io.Reader, contentType string, cfg filesOptions) (*File, error) {
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}
